[{"id":106759,"stt":1,"buoi":"Tuần 1-2","chuandaurachitiet":"[{"id":139958,"stt":2,"hoatdonggiangvien":{"vi":"Giới thiệu thông tin liên lạc giảng viên, trình bày sơ lược về khóa học bao gồm chuẩn đầu ra, mục tiêu và nội dung, tài liệu tham khảo, hướng dẫn cách học và cách đánh giá; \nTrình bày Chương 1: \n- Truyền đạt kiến thức và thảo luận về vật rắn biến dạng, toán tensor, biến đổi tọa độ; \n- Truyền đạt kiến thức và thảo luận về ngoại lực và nội lực; ứng suất - biến dạng;\nGửi bài giảng qua LMS và chia nhóm sinh viên.","en":"Introduce the instructor’s contact information; provide an overview of the course including learning outcomes, objectives, and content; reference materials; instructions on how to study and how assessment will be conducted.\nPresent Chapter 1: \n- Deliver knowledge and discuss deformable solids, tensor mathematics, and coordinate transformations.\n- Convey knowledge and discuss external and internal forces; stress-strain.\nUpload lecture materials to the LMS and divide students into groups."},"hoatdongsinhvien":{"vi":"- Thảo luận các nội dung giảng viên trình bày giới thiệu môn học;\n- Đọc trước ở nhà bài giảng và tài liệu học [1] chương 1 và 2, [2] chương 1  \n- Tập trung nghe bài giảng, ghi chú và thảo luận; \n- Thảo luận các nội dung giảng viên trình bày.\n- Làm bài tập về nhà [1] chương 1 và 2, [2] chương 1","en":"- Discuss the content presented by the instructor in the course introduction.\n- Read in advance at home the lecture and study materials: [1] Chapters 1 and 2, [2] Chapter 1.\n- Pay attention to the lecture, take notes, and participate in discussions.\n- Discuss the topics presented by the instructor.\n- Complete homework assignments: [1] Chapters 1 and 2, [2] Chapter 1."},"chuandaura":{"id":179367,"ma":"L.O.1.1","ten":{"vi":"Giải thích được các khái niệm về lực – chuyển vị, ứng suất – biến dạng và cơ tính của vật liệu.","en":"Explain concepts of forces–displacements, stress–strain, and material mechanics."}},"hoatdong":"[{\"id\